1	import { createHash } from "node:crypto";
2	import { db } from "./db";
3	import { verifyTOTP } from "./totp";
4	import { decryptSecret } from "./crypto-box";
5	
6	/**
7	 * TOTP verification primitives — deliberately a PLAIN module, not `"use server"`.
8	 *
9	 * SECURITY (2026-07-25): `verifyTotpForUser` used to live in `lib/actions-2fa.ts`,
10	 * which carries `"use server"` at the top. Every export of such a module is a
11	 * registered, network-callable server action. That made this function a public
12	 * endpoint taking an arbitrary `userId`, performing no authentication, no
13	 * ownership check and no rate limiting, returning a raw boolean — and mutating
14	 * state, because a matching backup code is consumed. `login()` is throttled to 10
15	 * attempts per 15 minutes per email+IP; calling this action directly bypassed that
16	 * completely, allowing unlimited TOTP and backup-code guessing against a named
17	 * account. Victim user IDs were obtainable from the team page.
18	 *
19	 * Keeping these here means they can only ever be reached by server code that
20	 * imports them (the login flow, and the 2FA management actions) — there is no
21	 * action ID for a client to call. Do NOT re-export any of this from a
22	 * `"use server"` module.
23	 */
24	
25	/** Hash a backup code for storage/comparison. Case- and whitespace-insensitive. */
26	export function hashCode(code: string): string {
27	  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
28	}
29	
30	/**
31	 * Resolve a user's TOTP secret, preferring the encrypted column and falling back
32	 * to any legacy plaintext value so already-enrolled users keep working.
33	 */
34	export function totpSecretOf(user: {
35	  totpSecret: string | null;
36	  totpSecretEnc: string | null;
37	}): string | null {
38	  return decryptSecret(user.totpSecretEnc) ?? user.totpSecret;
39	}
40	
41	/**
42	 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
43	 * valid one-time backup code (which is then removed).
44	 *
45	 * Callers MUST have already established that the request is entitled to attempt
46	 * a 2FA check for this user (i.e. the password stage passed) and MUST apply their
47	 * own rate limiting — this function deliberately has neither, which is precisely
48	 * why it must never be exposed as a server action.
49	 */
50	export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
51	  const user = await db.user.findUnique({ where: { id: userId } });
52	  if (!user || !user.totpEnabled) return false;
53	  const secret = totpSecretOf(user);
54	  if (!secret) return false;
55	
56	  if (verifyTOTP(secret, code)) return true;
57	
58	  // Fall back to consuming a backup code.
59	  const submitted = hashCode(code);
60	  const idx = user.backupCodes.indexOf(submitted);
61	  if (idx === -1) return false;
62	  const remaining = user.backupCodes.filter((_, i) => i !== idx);
63	  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
64	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
65	  return true;
66	}
