1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { headers } from "next/headers";
5	import { requireUser } from "./auth";
6	import { sendVerificationEmail, isEmailVerified } from "./email-verification";
7	
8	export type ResendState = { ok?: boolean; error?: string; message?: string };
9	
10	/**
11	 * Re-send the verification link to the signed-in account's own address.
12	 *
13	 * Note what this action does NOT accept: an address. It only ever mails
14	 * `user.email`, read from the session on the server. An action that took an
15	 * address parameter would be an open relay pointed at our own domain — anyone
16	 * with an account could have Nxeon-branded mail delivered to a stranger.
17	 *
18	 * Throttled per user AND per source IP: the per-user key stops one account
19	 * hammering one mailbox, and the per-IP key stops one script cycling through
20	 * many fresh accounts to do the same thing at scale.
21	 */
22	export async function resendVerificationEmail(): Promise<ResendState> {
23	  const user = await requireUser();
24	  if (isEmailVerified(user)) {
25	    return { ok: true, message: "That address is already confirmed." };
26	  }
27	  const hdrs = await headers();
28	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
29	  const outcome = await sendVerificationEmail(user, { throttleKey: `${user.id}:${ip}` });
30	  switch (outcome) {
31	    case "sent":
32	      return { ok: true, message: `Sent. Check ${user.email} — the link is good for 24 hours.` };
33	    case "already_verified":
34	      return { ok: true, message: "That address is already confirmed." };
35	    case "rate_limited":
36	      return {
37	        error:
38	          "We've sent several links already. Check your spam folder, then try again in an hour — or open a support ticket and we'll sort it out with you.",
39	      };
40	    default:
41	      // Never pretend a send worked. The whole B4 defect class is a screen that
42	      // reports success while nothing happened.
43	      return { error: "We couldn't send that email just now. Please try again shortly, or contact support." };
44	  }
45	}
46	
47	/** Form-action wrapper for `useActionState`. */
48	export async function resendVerificationAction(_prev: ResendState): Promise<ResendState> {
49	  const res = await resendVerificationEmail();
50	  revalidatePath("/dashboard");
51	  return res;
52	}
