import { NextRequest, NextResponse } from "next/server";
import { consumeVerificationToken } from "@/lib/email-verification";

/**
 * The target of the link in the verification email.
 *
 * A route handler rather than a page because redeeming a token is a WRITE, and a
 * write during a server component's render is a bug waiting to happen — React
 * may render a component more than once, and Next may prefetch it. Handlers run
 * exactly once per request. The outcome is then shown by /verify-email, which
 * renders and mutates nothing.
 *
 * `GET` is correct here despite being a mutation: the customer arrives by
 * clicking a link in mail, and the "unsafe method" objection does not apply
 * because the token IS the intent and it is single-use. Mail security scanners
 * that pre-fetch links will consume the token — which is why
 * `consumeVerificationToken` reports an already-verified account as a success
 * rather than an error. A scanner that can read the link is inside the
 * recipient's own mail infrastructure, so it fetching the link is evidence of
 * exactly the control we are testing for, not a bypass of it.
 */
export async function GET(req: NextRequest) {
  const token = req.nextUrl.searchParams.get("token") ?? "";
  let status: string;
  try {
    status = await consumeVerificationToken(token);
  } catch (e) {
    console.error("[verify-email] failed to consume token:", e);
    status = "error";
  }
  const dest = new URL("/verify-email", req.nextUrl.origin);
  dest.searchParams.set("status", status);
  return NextResponse.redirect(dest, { status: 303 });
}
