export const dynamic = "force-dynamic";

/**
 * Where /api/auth/verify-email lands the customer. Renders the outcome and,
 * whenever the outcome is anything other than success, an actual way forward —
 * a resend button when we know who they are, a sign-in link when we don't.
 *
 * A verification page whose failure state is a full stop would recreate B4's
 * shape in a new place: a screen that tells you no and leaves you there.
 */
const OUTCOMES: Record<
  string,
  { tone: "ok" | "bad"; title: string; body: string; resend: boolean }
> = {
  ok: {
    tone: "ok",
    title: "Email confirmed",
    body: "Thanks — your address is verified. Everything on your account is now unlocked, including ordering.",
    resend: false,
  },
  already: {
    tone: "ok",
    title: "Already confirmed",
    body: "This address was verified previously, so there's nothing left to do.",
    resend: false,
  },
  expired: {
    tone: "bad",
    title: "That link has expired",
    body: "Verification links are good for 24 hours. Send yourself a fresh one and it'll work straight away.",
    resend: true,
  },
  stale: {
    tone: "bad",
    title: "That link is out of date",
    body: "It was sent to an address this account no longer uses. Request a new link for your current address.",
    resend: true,
  },
  invalid: {
    tone: "bad",
    title: "That link isn't valid",
    body: "It may have already been used, or been cut short by your email client. Sending a new one is the quickest fix.",
    resend: true,
  },
  error: {
    tone: "bad",
    title: "Something went wrong",
    body: "We couldn't check that link just now. Please try again in a moment.",
    resend: true,
  },
};

export default async function VerifyEmailPage({
  searchParams,
}: {
  searchParams: Promise<{ status?: string }>;
}) {
  const { status } = await searchParams;
  const outcome = OUTCOMES[status ?? ""] ?? OUTCOMES.invalid;
  const user = await currentUser();

  return (
    <main className="flex min-h-screen items-center justify-center p-6">
      <div className="w-full max-w-sm">
        <Link href="/" className="mb-8 flex items-center justify-center">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src="/logo.png" alt="Nxeon" style={{ height: 34, width: "auto" }} className="object-contain" />
        </Link>
        <div className="card glow-brand">
          <div
            className={
              outcome.tone === "ok"
                ? "rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-3 text-sm text-emerald-300"
                : "rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300"
            }
          >
            <p className="font-semibold">{outcome.title}</p>
            <p className="mt-1 opacity-90">{outcome.body}</p>
          </div>

          {outcome.resend && user && (
            <div className="mt-4">
              <ResendVerification email={user.email} />
            </div>
          )}
          {outcome.resend && !user && (
            <p className="mt-4 text-sm text-slate-400">
              <Link href="/login" className="text-brand-300 hover:underline">
                Sign in
              </Link>{" "}
              and we&apos;ll offer you a new link straight away.
            </p>
          )}

          <div className="mt-4 text-center text-sm">
            <Link href={user ? "/dashboard" : "/login"} className="text-brand-300 hover:underline">
              {user ? "Go to your dashboard" : "Sign in"}
            </Link>
          </div>
        </div>
      </div>
    </main>
  );
}

