  const lines = src.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^export\s+(async\s+)?function\s+([A-Za-z0-9_]+)/) || lines[i].match(/^export\s+const\s+([A-Za-z0-9_]+)\s*=\s*(async)?/);
