"use server";

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { emailTemplateSeeds } from "@/prisma/seed-email-templates";

/**
 * Server actions backing the admin email-template editor. Every action is
 * gated on the `platform` area. All exports are async (this is a "use server"
 * module).
 */

export type EmailTemplateDTO = {
  id: string;
  key: string;
  name: string;
  category: string;
  subject: string;
  html: string;
  enabled: boolean;
  updatedAt: string;
};

/** List all templates (serialisable) for the editor, grouped-friendly order. */
export async function listEmailTemplates(): Promise<EmailTemplateDTO[]> {
  await requireArea("platform");
  const rows = await db.emailTemplate.findMany({
    orderBy: [{ category: "asc" }, { name: "asc" }],
  });
  return rows.map((r) => ({
    id: r.id,
    key: r.key,
    name: r.name,
    category: r.category,
    subject: r.subject,
    html: r.html,
    enabled: r.enabled,
    updatedAt: r.updatedAt.toISOString(),
  }));
}

/** Save subject/body (and optionally name/category) for a template. */
export async function saveEmailTemplate(input: {
  key: string;
  subject: string;
  html: string;
  name?: string;
  category?: string;
}): Promise<{ ok: boolean; error?: string }> {
  const admin = await requireArea("platform");
  const key = String(input.key ?? "").trim();
  const subject = String(input.subject ?? "").trim();
  const html = String(input.html ?? "");
  if (!key) return { ok: false, error: "Missing template key." };
  if (!subject) return { ok: false, error: "Subject cannot be empty." };
  if (!html.trim()) return { ok: false, error: "Body cannot be empty." };

  try {
    await db.emailTemplate.update({
      where: { key },
      data: {
        subject,
        html,
        ...(input.name ? { name: String(input.name).trim() } : {}),
        ...(input.category ? { category: String(input.category).trim() } : {}),
      },
    });
    await db.auditLog.create({
      data: { userId: admin.id, action: "admin.email_template_saved", detail: key },
    });
    return { ok: true };
  } catch (e) {
    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
  }
}

/** Enable/disable a template (disabled → the built-in default is used). */
export async function toggleEmailTemplate(
  key: string,
  enabled: boolean,
): Promise<{ ok: boolean; error?: string }> {
  const admin = await requireArea("platform");
  try {
    await db.emailTemplate.update({ where: { key: String(key) }, data: { enabled: !!enabled } });
    await db.auditLog.create({
      data: {
        userId: admin.id,
        action: "admin.email_template_toggled",
        detail: `${key} → ${enabled ? "enabled" : "disabled"}`,
      },
    });
    return { ok: true };
  } catch (e) {
    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
  }
}

/** Restore a template's subject/body/name/category to the seeded canonical copy. */
export async function resetEmailTemplate(key: string): Promise<{ ok: boolean; error?: string; template?: EmailTemplateDTO }> {
  const admin = await requireArea("platform");
  const seed = emailTemplateSeeds.find((t) => t.key === key);
  if (!seed) return { ok: false, error: "No canonical template exists for this key." };
  try {
    const row = await db.emailTemplate.upsert({
      where: { key: seed.key },
      create: { key: seed.key, name: seed.name, category: seed.category, subject: seed.subject, html: seed.html, enabled: true },
      update: { name: seed.name, category: seed.category, subject: seed.subject, html: seed.html },
    });
    await db.auditLog.create({
      data: { userId: admin.id, action: "admin.email_template_reset", detail: key },
    });
    return {
      ok: true,
      template: {
        id: row.id,
        key: row.key,
        name: row.name,
        category: row.category,
        subject: row.subject,
        html: row.html,
        enabled: row.enabled,
        updatedAt: row.updatedAt.toISOString(),
      },
    };
  } catch (e) {
    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
  }
}
