// ---------- Referral rewards ----------

/**
 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
 * Callable from `topUp` / `orderServer` in lib/actions.ts after a paid action.
 */
export async function maybeRewardReferral(userId: string): Promise<boolean> {
  await assertInternalGrowthCaller(userId);
  // Feature flag: the referral program can be switched off platform-wide.
  if (!(await getSettingBool("feature_referrals", true))) return false;

  // Settings → Growth writes `referral_reward_cents` and displays it, but NOTHING
  // read it — the payout used the env-backed `referralRewardCents()` instead, so an
  // operator changing the reward saw "Saved." and the platform kept paying the old
  // amount. Same shape as the domain markup showing 0% while charging 25%, and the
  // auto-suspend switch that silenced nothing.
  //
  // Clamped, and the ceiling matters more here than anywhere else: this reward is
  // paid to BOTH the referrer and the referred user, so a stray digit costs twice
  // per signup and scales with signup volume. 100_000 cents = $1,000 a side is
  // already absurd; anything beyond it is certainly a typo.
  const reward = Math.min(
    Math.max(await getSettingInt("referral_reward_cents", referralRewardCents()), 0),
    100_000
  );
  if (reward <= 0) return false;

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user || !user.referredById || user.referralRewardedAt) return false;
  const referrerId = user.referredById;

  // Atomically claim the reward; if another concurrent action already did, bail.
  const claim = await db.user.updateMany({
    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
    data: { referralRewardedAt: new Date() },
  });
  if (claim.count === 0) return false;

  await db.$transaction([
    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
    db.walletTransaction.create({
      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
    }),
    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
    db.walletTransaction.create({
      data: {
        userId: referrerId,
        amountCents: reward,
        description: "Referral bonus — you referred a friend",
      },
    }),
  ]);

  // Best-effort in-app notifications, filtered through the notification policy.
  //
  // `referral_bonus` is ACCOUNT tier, so the in-app bell is never suppressed —
  // these rows are the customer's record of money that entered their wallet, and
  // hiding a credit would be the same "it silently disappeared" failure the
  // preferences exist to cure. The gate is here anyway so the tier in
  // `lib/prefs.ts` stays the single decider: if this kind is ever reclassified,
  // the filter starts biting without anyone having to remember this call site.
  try {
    const rows = [
      {
        userId,
        title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
        href: "/dashboard/billing",
      },
      {
        userId: referrerId,
        title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
        href: "/dashboard/refer",
      },
    ];
    const allowed: typeof rows = [];
    for (const row of rows) {
      if (await mayDeliverTo(row.userId, "referral_bonus", "inapp")) allowed.push(row);
    }
    if (allowed.length > 0) await db.notification.createMany({ data: allowed });
  } catch {
    /* best-effort */
  }
  return true;
}

