/**
 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
 * caller owns the TARGET server (authz + a stricter rate limit than create),
 * validates the source connection details, then SSHes into the source and
 * inventories web roots / home directories / databases — never writing anything
 * on the source and never persisting the supplied credentials.
 *
 * The plaintext SSH/DB passwords are used in-memory for this one call only and
 * are NOT stored anywhere; the client re-supplies them to createMigration once
 * the customer confirms what to move. Returns a secret-free ScanResult.
 *
 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
 * a real SSH connection, so staging stays fully self-contained.
 */
export async function scanSource(input: {
  serverId: string;
  sourceHost: string;
  sourcePort?: number;
  sourceUser?: string;
  sourcePassword: string;
  dbUser?: string;
  dbPassword?: string;
}): Promise<{ error?: string; scan?: ScanResult }> {
  const { user } = await ownedTargetServer(input.serverId);

  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
  // than migration creation to stop the wizard being used to probe hosts.
  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
  if (!rl.ok) {
    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
  }

  const host = (input.sourceHost ?? "").trim();
  if (!host || host.length > 253 || !HOST_RE.test(host)) {
    return { error: "Enter a valid source host — an IP address or domain name." };
  }
  const port = input.sourcePort ?? 22;
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return { error: "SSH port must be between 1 and 65535." };
  }
  const sourceUser = (input.sourceUser ?? "root").trim();
  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
    return { error: "Enter the SSH username on the source server." };
  }
  if (!input.sourcePassword || input.sourcePassword.length < 1) {
    return { error: "Enter the SSH password for the source server." };
  }

  await db.auditLog.create({
    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
  }).catch(() => {});

  // SANDBOX: never touch the outside world — hand back synthetic detection.
  if (SANDBOX) {
    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
  }

  // Hard overall timeout so a slow/hostile source can't hang the request.
  const HARD_TIMEOUT_MS = 90_000;
  try {
    const scan = await Promise.race<ScanResult>([
      detectSource({
        host,
        port,
        user: sourceUser,
        password: input.sourcePassword,
        dbUser: input.dbUser?.trim() || undefined,
        dbPassword: input.dbPassword || undefined,
      }),
      new Promise<ScanResult>((_, reject) =>
        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
      ),
    ]);
    return { scan };
  } catch (e: any) {
    const msg = `${e?.message ?? e}`;
    // Map the common connection failures to friendly, non-leaky copy.
    if (/authentication|denied|password/i.test(msg)) {
      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
    }
    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
      return { error: "Couldn't reach the source server — check the host and SSH port." };
    }
