 *   1. `beginTotpEnrollment()` -> generates a secret, stores it (totpEnabled
 *      stays false), and returns the otpauth URI + secret for the UI to show.
 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
 *      success `totpEnabled` flips true and backup codes are generated.
 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
 *      the account password.
 *
 * Backup codes are one-time; only their sha256 hashes are stored.
 */


/** Generate N human-friendly one-time backup codes (plaintext, for display). */
function makeBackupCodes(n = 10): string[] {
  return Array.from({ length: n }, () => {
    const raw = randomBytes(5).toString("hex"); // 10 hex chars
    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
  });
}

/**
 * Step 1: create (but do not yet activate) a TOTP secret.
 *
 * Return shape keeps `secret`/`otpauthUrl` present (empty on refusal) so the
 * existing typed caller (`useState<{secret;otpauthUrl}>`) still compiles; an
 * optional `error` is populated when enrolment is refused.
 */
export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string; error?: string }> {
  const user = await requireUser();

  // Block enrolment while impersonating: the real acting account must be the
  // same account being enrolled, so an admin can't seed a customer's 2FA.
  const real = await realUser();
  if (!real || real.id !== user.id) {
    return { secret: "", otpauthUrl: "", error: "You can't set up 2FA while impersonating another account." };
  }

  // Refuse to overwrite an ALREADY-ACTIVE secret — doing so silently disabled
  // the user's working 2FA (totpEnabled=false + fresh secret) with no re-auth.
  if (user.totpEnabled === true) {
    return { secret: "", otpauthUrl: "", error: "Disable your current 2FA first." };
  }

  const secret = generateSecret();
  // Store encrypted at rest; clear any legacy plaintext value for this account.
  await db.user.update({
    where: { id: user.id },
    data: { totpSecretEnc: encryptSecret(secret), totpSecret: null, totpEnabled: false },
  });
  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
}

/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
export async function confirmTotpEnrollment(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
  const user = await requireUser();
  const code = String(formData.get("code") ?? "");
  const secret = totpSecretOf(user);
  if (!secret) return { error: "Start enrolment first." };
  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect. Try again." };

  const backupCodes = makeBackupCodes();
  await db.user.update({
    where: { id: user.id },
    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
  revalidatePath("/dashboard/settings");
  return { ok: true, backupCodes };
}

/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
export async function regenerateBackupCodes(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; backupCodes?: string[] }> {
  const user = await requireUser();
  const code = String(formData.get("code") ?? "");
  const secret = totpSecretOf(user);
  if (!user.totpEnabled || !secret) return { error: "2FA is not enabled." };
  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect." };
  const backupCodes = makeBackupCodes();
  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
  return { backupCodes };
}

/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
export async function disableTotp(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const proof = String(formData.get("proof") ?? "");
  if (!user.totpEnabled) return { error: "2FA is not enabled." };

  const secret = totpSecretOf(user);
  const codeValid =
    (secret ? verifyTOTP(secret, proof) : false) ||
    (await verifyTotpForUser(user.id, proof));
  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
  if (!codeValid && !passwordValid) {
    return { error: "Enter a valid authenticator code, backup code, or your password." };
  }

  await db.user.update({
    where: { id: user.id },
    data: { totpEnabled: false, totpSecret: null, totpSecretEnc: null, backupCodes: [] },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

