import { NextResponse } from "next/server";
import { logError } from "@/lib/log";
import { checkRateLimit } from "@/lib/rate-limit";

export const runtime = "nodejs";

/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
function clientIp(req: Request): string {
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const first = xff.split(",")[0]?.trim();
  return first || "unknown";
}

// Receives client-side error reports from the error boundaries. Payload is
// size-capped and never trusted beyond logging.
export async function POST(req: Request) {
  // Unauthenticated endpoint: throttle per-IP so it can't be used to amplify
  // the ops webhook or pin request slots. Silently no-op when over the limit.
  const ip = clientIp(req);
  const rl = checkRateLimit(`log:${ip}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) {
    return new NextResponse(null, { status: 204 });
  }

  try {
    const body = (await req.json().catch(() => ({}))) as {
      context?: string;
      message?: string;
      digest?: string;
      path?: string;
      stack?: string;
    };
    const clip = (s: unknown, n: number) => (typeof s === "string" ? s.slice(0, n) : undefined);
    // Fire-and-forget: the webhook fan-out in lib/log.ts awaits an outbound
    // fetch, so do NOT block the response on it. Errors are swallowed there.
    void logError(clip(body.context, 80) ?? "client-error", { message: clip(body.message, 500), digest: clip(body.digest, 80) }, {
      path: clip(body.path, 200),
      stack: clip(body.stack, 2000),
      source: "client",
    });
  } catch {
    // ignore malformed reports
  }
  return NextResponse.json({ ok: true });
}

/**
 * Lightweight, dependency-free error logging.
 * Always writes a structured line to stderr (captured by journald); if
 * NXEON_ERROR_WEBHOOK is set, also POSTs a compact alert (best-effort).
 * Swap in Sentry later by adding a call here — this is the single choke point.
 */
type Level = "error" | "warn" | "info";

export async function logEvent(
  level: Level,
  context: string,
  detail: Record<string, unknown> = {},
): Promise<void> {
  const line = {
    ts: new Date().toISOString(),
    level,
    context,
    ...detail,
    env: process.env.NXEON_ENV ?? "production",
  };
  const serialized = JSON.stringify(line);
  if (level === "error") console.error(`[nxeon] ${serialized}`);
  else if (level === "warn") console.warn(`[nxeon] ${serialized}`);
  else console.log(`[nxeon] ${serialized}`);

  const webhook = process.env.NXEON_ERROR_WEBHOOK;
  if (webhook && level === "error") {
    // Fire-and-forget: never make a request wait on (or fail from) the outbound
    // alert. The caller does not await the fetch — only the stderr line above is
    // synchronous. Errors are swallowed so logging can never throw.
    void fetch(webhook, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ text: `🚨 Nxeon ${context}: ${detail.message ?? "error"}`, detail: line }),
      signal: AbortSignal.timeout(3000),
    }).catch(() => {});
  }
}

export function logError(context: string, error: unknown, extra: Record<string, unknown> = {}) {
  const e = error as { message?: string; stack?: string; digest?: string };
  return logEvent("error", context, {
    message: e?.message ?? String(error),
    stack: e?.stack?.split("\n").slice(0, 6).join("\n"),
    digest: e?.digest,
    ...extra,
  });
}
