/**
 * Which 30-second step a submitted code belongs to, or null if it belongs to
 * none within the ±1 window. Constant-time comparison per step.
 *
 * `verifyTOTP` is the boolean form of this and is what most callers want. The
 * counter itself is needed by exactly one caller — the login path — because RFC
 * 6238 §5.2 requires that a code be accepted ONCE, and "once" can only be
 * enforced against a specific step. A bare boolean cannot express which of the
 * three candidate codes matched, so a replayed code is indistinguishable from a
 * fresh one. See lib/totp-verify.ts.
 *
 * The whole window is always walked, even after a match, so the time this takes
 * does not reveal WHICH step matched (and therefore does not reveal the
 * verifier's clock offset).
 */
export function matchTOTPCounter(
  secret: string,
  code: string,
  atMs: number = Date.now(),
): number | null {
  const cleaned = (code ?? "").replace(/\s/g, "");
  if (!/^\d{6}$/.test(cleaned)) return null;
  const counter = Math.floor(atMs / 1000 / STEP_SECONDS);
  let matched: number | null = null;
  for (let w = -1; w <= 1; w++) {
    const expected = hotp(secret, counter + w);
    const a = Buffer.from(expected);
    const b = Buffer.from(cleaned);
    if (a.length === b.length && timingSafeEqual(a, b) && matched === null) {
      matched = counter + w;
    }
  }
  return matched;
}

/**
 * Verify a submitted code against the secret with a ±1 step window
 * (tolerates minor clock drift). Constant-time comparison per step.
 */
export function verifyTOTP(secret: string, code: string, atMs: number = Date.now()): boolean {
  return matchTOTPCounter(secret, code, atMs) !== null;
}

