/**
 * How long a spent TOTP step stays remembered. A code is valid across a ±1 step
 * window, so the last step that can still accept a given code ends 60s after the
 * step it was minted for begins; 90s covers that with margin and then forgets,
 * which keeps the marker store bounded.
 */
const TOTP_REPLAY_TTL_MS = 90_000;

/**
 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
 * valid one-time backup code (which is then removed).
 *
 * Callers MUST have already established that the request is entitled to attempt
 * a 2FA check for this user (i.e. the password stage passed) and MUST apply their
 * own rate limiting — this function deliberately has neither, which is precisely
 * why it must never be exposed as a server action.
 *
 * BOTH kinds of proof this accepts are ONE-TIME, and neither was:
 *
 *  - A TOTP code was accepted for as long as it verified, which is up to 90
 *    seconds across the drift window, any number of times. RFC 6238 §5.2 is
 *    explicit that a code must be accepted once; "you must also know the
 *    password" is not a substitute, because the scenario this protects against
 *    is precisely the one where the password is already known and the code was
 *    observed — a shoulder-surf, a screenshot, a code read back over the phone
 *    to someone claiming to be support. The step that a code belongs to is now
 *    claimed on first use and refused thereafter.
 *
 *  - A backup code was consumed with a read-modify-write: read the array, filter
 *    the used entry out, write the array back. Two requests submitting the SAME
 *    backup code concurrently both read it as present, both matched, and both
 *    returned true — one printed one-time code was worth two sign-ins. The
 *    removal is now a compare-and-swap: the UPDATE only applies while the code is
 *    still in the array, so exactly one of the racers can win it.
 *
 * A rejected replay is reported exactly like a wrong code — same `false`, no
 * separate signal — so this cannot be used to probe which codes have been seen.
 */
export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user || !user.totpEnabled) return false;
  const secret = totpSecretOf(user);
  if (!secret) return false;

  const step = matchTOTPCounter(secret, code);
  if (step !== null) {
    // Single-use: the first presentation of this step wins, later ones do not.
    return claimOnce(`totp:${user.id}:${step}`, TOTP_REPLAY_TTL_MS);
  }

  // Fall back to consuming a backup code.
  const submitted = hashCode(code);
  if (!user.backupCodes.includes(submitted)) return false;
  const remaining = user.backupCodes.filter((c) => c !== submitted);
