  // WHERE clause, so a concurrent request that already spent it updates zero
  // rows and is refused. `update` (which matches on id alone) could not fail.
  const claimed = await db.user.updateMany({
    where: { id: user.id, backupCodes: { has: submitted } },
    data: { backupCodes: remaining },
  });
  if (claimed.count === 0) return false;
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
  return true;
}

