 * A code is proof ONCE — RFC 6238 §5.2
 *
 * `verifyTotpForUser` returned true for as long as a code verified, which is up
 * to 90 seconds across the ±1 drift window, any number of times. "You also need
 * the password" is not a mitigation, because the case this protects against is
 * exactly the one where the password is already known and the code was observed
 * — a shoulder-surf, a screenshot, a code read out to someone claiming to be
 * support. Enforcing "once" needs to know WHICH of the three candidate steps a
 * code belonged to, and a boolean cannot say.
 * ================================================================== */

test("matchTOTPCounter names the step a code belongs to", () => {
  const secret = generateSecret();
  const at = 1_700_000_000_000;
  const step = Math.floor(at / 1000 / 30);
  assert.equal(matchTOTPCounter(secret, generateTOTP(secret, at), at), step);
  // The drift window is identified as the step it really is, not as "now".
  assert.equal(matchTOTPCounter(secret, generateTOTP(secret, at - 30_000), at), step - 1);
  assert.equal(matchTOTPCounter(secret, generateTOTP(secret, at + 30_000), at), step + 1);
});

test("matchTOTPCounter distinguishes the three steps, which is what makes replay detectable", () => {
  const secret = generateSecret();
  const at = 1_700_000_000_000;
  const steps = new Set([
    matchTOTPCounter(secret, generateTOTP(secret, at - 30_000), at),
    matchTOTPCounter(secret, generateTOTP(secret, at), at),
    matchTOTPCounter(secret, generateTOTP(secret, at + 30_000), at),
  ]);
  assert.equal(steps.size, 3, "three accepted codes must map to three distinct claims");
  assert.ok(![...steps].includes(null));
});

test("matchTOTPCounter returns null for everything verifyTOTP rejects", () => {
  const secret = generateSecret();
  const at = 1_700_000_000_000;
  const good = generateTOTP(secret, at);
  const wrong = good === "000000" ? "111111" : "000000";
  for (const bad of [wrong, "", "12345", "abcdef", "1234567"]) {
    assert.equal(matchTOTPCounter(secret, bad, at), null, `must reject ${JSON.stringify(bad)}`);
    assert.equal(verifyTOTP(secret, bad, at), false, "and the boolean form must agree");
  }
  // Two steps out is outside the window for both.
  assert.equal(matchTOTPCounter(secret, generateTOTP(secret, at), at + 90_000), null);
});

test("verifyTOTP is exactly the boolean projection of matchTOTPCounter", () => {
  // If these two ever disagree, one caller is enforcing a different window from
  // the other — which is how a 'fix' to one silently reopens the other.
  const secret = generateSecret();
  for (let i = 0; i < 200; i++) {
    const at = 1_700_000_000_000 + i * 7_000;
    const code = i % 3 === 0 ? generateTOTP(secret, at) : String(i).padStart(6, "0");
    assert.equal(verifyTOTP(secret, code, at), matchTOTPCounter(secret, code, at) !== null);
