/* ================================================================== *
 * The rate-limit key was a field the caller filled in
 *
 * nginx forwards `X-Forwarded-For: $proxy_add_x_forwarded_for`, which APPENDS
 * the peer it saw to whatever the caller sent. So the LEFTMOST entry is
 * caller-authored text, and `(xff ?? "").split(",")[0]` — the expression that
 * keyed the login, register, password-reset, verification-resend and wallet
 * top-up throttles — returns whatever the caller typed.
 *
 * Measured through the real staging nginx: 25 POSTs with a rotating
 * X-Forwarded-For never tripped a 20/minute limit that a fixed value trips on
 * the 21st, and a forged value was written verbatim into the visitor log.
 * ================================================================== */

/** `(…get("x-forwarded-for") …).split(",")[0]` in any spelling. */
const LEFTMOST_XFF = /x-forwarded-for[\s\S]{0,120}?\.split\(","\)\s*\[\s*0\s*\]/;

/**
 * Call sites that STILL derive the caller's address from the leftmost hop, with
 * the owning file. This list is an inventory of remaining exposure, not an
 * approval: the assertion is a SUBSET check, so fixing one shrinks it and the
 * suite stays green, while introducing a NEW one turns it red.
 *
 * `lib/actions.ts` is the one that matters most and is not fixed here because it
 * was owned by another change in flight: `login` keys its throttle this way, so
 * the 10-attempts-per-15-minutes lockout that is supposed to stop password AND
 * 2FA guessing against a named account can be stepped around by varying a
 * header. Replace each with `clientIp(await headers())` from lib/rate-limit.ts.
 */
const XFF_STILL_OUTSTANDING = new Set([
  "lib/actions.ts", // register / login / topUp — login is the severe one
  "lib/tools/api.ts", // clientIp() for the public /api/tools/* throttles
]);

test("no NEW call site keys anything on the caller-supplied first hop", () => {
  const offenders = new Set<string>();
  const walk = (dir: string, prefix: string) => {
    for (const entry of readdirSync(new URL(dir, import.meta.url), { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (entry.name === "node_modules" || entry.name === ".next") continue;
        walk(`${dir}${entry.name}/`, `${prefix}${entry.name}/`);
      } else if (/\.tsx?$/.test(entry.name)) {
        let src: string;
        try {
          src = code(`${dir}${entry.name}`);
        } catch {
          continue; // a sibling edit removed it mid-run
        }
        if (LEFTMOST_XFF.test(src)) offenders.add(`${prefix}${entry.name}`);
      }
    }
  };
  walk("../lib/", "lib/");
  walk("../app/", "app/");
  walk("../worker/", "worker/");

  const unexpected = [...offenders].filter((f) => !XFF_STILL_OUTSTANDING.has(f)).sort();
  assert.deepEqual(
    unexpected,
    [],
    "These read the FIRST X-Forwarded-For hop, which nginx does not write — the\n" +
      "caller does. Any rate limit, audit row or abuse decision keyed on it is\n" +
      "defeated by sending a different fake value each request.\n" +
      "Use `clientIp(await headers())` from lib/rate-limit.ts (server actions) or\n" +
      "`trustedClientIp(req)` from app/api/_lib/client-ip.ts (route handlers).\n" +
      "New offenders:\n  " + unexpected.join("\n  "),
  );
});

test("the auth surface itself no longer trusts the caller's hop", () => {
  // These are the files this audit owned. They must be clean unconditionally —
  // the inventory above is for other people's in-flight work, not for these.
  for (const f of ["../lib/actions-account.ts", "../lib/actions-verify-email.ts", "../lib/rate-limit.ts"]) {
    assert.ok(!LEFTMOST_XFF.test(code(f)), `${f} must not read the first X-Forwarded-For hop`);
  }
  const account = code("../lib/actions-account.ts");
  const resend = code("../lib/actions-verify-email.ts");
  assert.match(account, /clientIp\(await headers\(\)\)/, "the reset throttle is keyed on the attested address");
  assert.match(resend, /clientIp\(await headers\(\)\)/, "so is the verification-resend throttle");
});

/* ================================================================== *
 * A reset request must take the same time whether or not the account exists
 * ================================================================== */

test("H7b: requestPasswordReset does not wait for the mail it only sometimes sends", () => {
  const reset = /export async function requestPasswordReset\([\s\S]*?\n}/.exec(ACCOUNT)?.[0] ?? "";
  assert.ok(reset, "found requestPasswordReset");
  // The reply was already identical either way — but only the known-address
  // branch opened an SMTP conversation before producing it. The wording revealed
  // nothing and the clock revealed everything, at one sample per address.
  assert.ok(
    !/await sendMail\(/.test(reset),
    "awaiting the send makes a known address measurably slower than an unknown one, " +
      "which is a working account-enumeration oracle against the customer list",
  );
  assert.match(reset, /void \(async \(\) => \{/, "the send is detached from the response");
  assert.match(reset, /\.catch\(/, "and its rejection is handled, so a dead mail server cannot kill the process");
  // The non-enumerating reply itself must survive all of this.
  assert.match(reset, /return \{ sent: true \}/);
  assert.ok(!/error:/.test(reset), "no branch reports that an address is unknown");
});

/* ================================================================== *
 * A session cookie and an impersonation cookie are the same kind of string
 *
 * Both are HS256 over the same AUTH_SECRET, so `jwtVerify` accepts either in
 * either slot. Nothing distinguished them, so moving the value of
 * `nxeon_session_imp` into `nxeon_session` produced a genuine session as the
 * impersonated customer — not flagged as impersonation, so no banner, and
 * `audit()` stops appending `actingAdmin=…`. Every action after that is recorded
 * as the customer's own.
 * ================================================================== */

const AUTH = code("../lib/auth.ts");

test("the two token kinds are distinguishable, and a grant cannot become a session", () => {
  assert.match(AUTH, /SignJWT\(\{ sub: userId, sv: [^}]*typ: "session" \}\)/, "sessions are marked");
  assert.match(AUTH, /SignJWT\(\{ sub: targetUserId, adminId: real\.id, typ: "imp" \}\)/, "grants are marked");
  assert.match(AUTH, /function assertSessionToken/, "and something checks the mark");
  // The decisive rule: an impersonation grant carries adminId, so its presence
  // alone disqualifies a token from being a session — this stays correct even
  // for tokens minted before `typ` existed, which is why nobody is signed out.
  assert.match(AUTH, /if \(payload\.adminId !== undefined\) return false;/);
  assert.match(AUTH, /payload\.typ === undefined \|\| payload\.typ === "session"/, "old sessions still verify");
  // Both entry points that turn a cookie into an identity must apply it.
  const real = /export const realUser = cache\([\s\S]*?\n\}\);/.exec(AUTH)?.[0] ?? "";
  assert.ok(real, "found realUser");
  assert.match(real, /if \(!assertSessionToken\(payload\)\) return null;/);
  const signedIn = /export async function isSignedIn\([\s\S]*?\n\}/.exec(AUTH)?.[0] ?? "";
  assert.match(signedIn, /assertSessionToken\(payload\)/);
  // And the impersonation cookie must require its own mark, so a session token
  // cannot be replayed into that slot either.
  assert.match(AUTH, /payload\.typ === "imp" && payload\.adminId === real\.id/);
});

test("impersonation re-checks the target against the CURRENT row, not the 2h-old token", () => {
  const cur = /export const currentUser = cache\([\s\S]*?\n\}\);/.exec(AUTH)?.[0] ?? "";
  assert.ok(cur, "found currentUser");
  assert.match(
    cur,
    /if \(target && !target\.suspended && target\.role !== "ADMIN"\) return target;/,
    "suspended: realUser refuses a session for a suspended account, and impersonation " +
      "must not be a side door that resurrects one. ADMIN: refused at mint time, but a " +
      "customer promoted mid-impersonation would otherwise make the impersonator's " +
      "currentUser() an ADMIN — and requireAdmin is built on currentUser.",
  );
  // requireAdmin really is built on the effective user, which is what makes the
  // ADMIN re-check load-bearing rather than decorative.
  assert.match(AUTH, /export async function requireAdmin\(\): Promise<User> \{\s*const user = await requireUser\(\);/);
  assert.match(AUTH, /export async function requireUser\(\): Promise<User> \{\s*const user = await currentUser\(\);/);
});
