--- current maybeRewardReferral head ---
export async function maybeRewardReferral(userId: string): Promise<boolean> {
  await assertInternalGrowthCaller(userId);
  // Feature flag: the referral program can be switched off platform-wide.
  if (!(await getSettingBool("feature_referrals", true))) return false;

  // Settings → Growth writes `referral_reward_cents` and displays it, but NOTHING
  // read it — the payout used the env-backed `referralRewardCents()` instead, so an
  // operator changing the reward saw "Saved." and the platform kept paying the old
  // amount. Same shape as the domain markup showing 0% while charging 25%, and the
  // auto-suspend switch that silenced nothing.
  //
  // Clamped, and the ceiling matters more here than anywhere else: this reward is
  // paid to BOTH the referrer and the referred user, so a stray digit costs twice
  // per signup and scales with signup volume. 100_000 cents = $1,000 a side is
  // already absurd; anything beyond it is certainly a typo.
  const reward = Math.min(
    Math.max(await getSettingInt("referral_reward_cents", referralRewardCents()), 0),
    100_000
  );
  if (reward <= 0) return false;

"use server";

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { headers } from "next/headers";
import type { Coupon } from "@prisma/client";
import { db } from "./db";
import { requireUser, requireAdmin, realUser } from "./auth";
import { getSettingBool, getSettingInt } from "./settings";

/**
 * Internal-only guard for `maybeRewardReferral` below.
 *
 * It is exported from this "use server" module, so Next.js registers it as a
 * callable action endpoint that would otherwise let anyone POST a raw `userId`
 * and mint referral credit for an account they do not own. Its legitimate
 * callers are internal: the topUp / orderServer server actions, the
 * order-placement flow (lib/order.ts) and the Stripe webhook (lib/stripe.ts).
 *
 * Three deny rules, in order, each closing a different way in:
 *
 * 1. SESSION PRESENT ⇒ it must be the account being credited. This is the rule
 *    that used to be reached only when a `next-action` header was present.
 *
 * 2. NO SESSION, BUT DISPATCHED AS AN ACTION ⇒ refuse. An anonymous POST to the
 *    action endpoint has no business naming someone else's `userId`.
 *
 * 3. NON-STRING `userId` ⇒ refuse. Next.js ALSO dispatches actions from a plain
 *    no-JavaScript form POST, where the action id travels in the body as
 *    `$ACTION_ID_…` and NO `next-action` header is sent at all (see
 *    `areAllActionIdsValid` in next/dist/server/app-render/action-handler.js).
 *    Rule 2 cannot see that path. React hands such an invocation the FormData as
 *    its first argument, so the type check is what actually stops it — an
 *    explicit refusal rather than relying on Prisma to choke on the wrong shape.
 *
 * The old guard's ONLY test was "is the `next-action` header present?", and it
 * treated a missing header as proof of a trusted server-to-server call. Rules 1
 * and 3 hold whether or not that header exists.
 *
 * What still gets through, correctly: the Stripe webhook and the checkout
 * confirm route (lib/stripe.ts, lib/order.ts). A webhook carries no session
 * cookie and is not an action dispatch, and it passes a real string id.
 *
 * `grantSignupCredit` is NOT here any more. It had exactly one caller — the
 * `register` action — and being an export made it a public endpoint whose only
 * protection was this guard. It now lives as a private helper inside
 * lib/actions.ts, so there is no endpoint to defend.
 */
async function assertInternalGrowthCaller(userId: string): Promise<void> {
  if (typeof userId !== "string" || !userId) throw new Error("FORBIDDEN");
  const real = await realUser();
  if (real) {
    if (real.id !== userId) throw new Error("FORBIDDEN");
    return;
  }
  const h = await headers();
  if (h.has("next-action")) throw new Error("FORBIDDEN");
}
